import math
from part1 import danger, caution, tip, check, table, fig

def hw_loss(gpm, d_in, C=150):
    return 0.2083*(100/C)**1.852*gpm**1.852/d_in**4.8655

def friction_table():
    sizes = [("1 in", 1.049), ("1½ in", 1.610), ("2 in", 2.067), ("3 in", 3.068), ("4 in", 4.026), ("6 in", 6.065)]
    flows = [10, 20, 30, 50, 75, 100, 150, 200, 300]
    rows = []
    for q in flows:
        row = [f"{q} gpm <span class='small'>({q*0.06309:.1f} L/s)</span>"]
        for nm, d in sizes:
            v = q*0.4085/d**2  # ft/s
            hf = hw_loss(q, d)
            if v > 8: row.append("<span style='color:#b0b8bf'>—</span>")
            else:
                s = f"{hf:.2f}" if hf < 10 else f"{hf:.0f}"
                if hf > 3: s = f"<span style='color:#b0b8bf'>{s}</span>"
                elif hf <= 1.0: s = f"<b>{s}</b>"
                row.append(s)
        rows.append(row)
    return table(["Flow"] + [f"{n} PVC" for n, _ in sizes], rows, numcols=(1,2,3,4,5,6))

def sample_numbers():
    loss = hw_loss(60, 3.068)*10
    return loss

def build(D):
    h = []
    h.append('<h1 class="part" id="p3"><small>Part 3 · Main project</small>Micro-Hydro: Powering a House with Falling Water</h1>')
    h.append('<p>If you have a stream that drops downhill on or next to your land, micro-hydro is the best off-grid power source there is. Unlike solar and wind, it runs <b>24 hours a day</b>, often with its highest output in winter when you need it most. A turbine producing a steady 500 W delivers 12 kWh per day — as much as about 3–4 kW of solar panels in a northern winter. Systems built with care run for decades with little more than a screen to clean.</p>')
    h.append(fig(D.hydro_layout(), "<b>Figure 4. Micro-hydro system layout.</b> Water is diverted at the intake, settles in the forebay, drops through the pressurized penstock to the turbine, and returns to the stream through the tailrace. Electricity travels to the house by buried cable."))
    h.append('<h2 id="site">3.1 Site assessment: head and flow</h2>')
    h.append('<p>Hydro power depends on just two site numbers: <b>head</b> (vertical drop, in feet or metres) and <b>flow</b> (volume of water per second or minute). High head with low flow and low head with high flow can produce the same power, but they need very different equipment. Measure both carefully — they decide everything else.</p>')
    h.append('<h3>Measuring head</h3>')
    h.append('<ul><li><b>Hose and pressure gauge (best, simplest):</b> run a garden hose or poly pipe from the proposed intake down to the proposed turbine site, fill it completely, purge all air, cap the bottom with an accurate pressure gauge and read with <b>no water flowing</b>. Head (ft) = psi × 2.31; head (m) = kPa ÷ 9.81 (or bar × 10.2). For long drops, measure in segments with several hoses and add the results.</li><li><b>Level-and-stick (‘board’) method:</b> lay a straight board level from a point on the ground; measure straight down from its downhill end; move to that spot and repeat (Figure 5). Accurate to a few percent with care.</li><li><b>Water-level tube:</b> a long clear tube filled with water; the water stands at the same height at both ends — the same idea in a flexible form.</li><li><b>Sight level / laser level / survey:</b> accurate and fast if available.</li><li>Topographic maps, GPS and phone altimeters give a quick first guess only — they can be off by 3–10 m (10–30 ft).</li></ul>')
    h.append(fig(D.head_measure(), "<b>Figure 5. Measuring head.</b> Left: stepping down the slope with a straight board, carpenter’s level and measuring stick. Right: the hose-and-gauge method — static pressure is directly proportional to vertical drop."))
    h.append('<h3>Measuring flow</h3>')
    h.append('<p>Measure flow in the <b>driest part of the year</b> (late summer in most of North America; late winter for frozen Northern streams; end of the dry season in Mexico and Central America) and design for that. Ask neighbors or old-timers whether the stream ever goes dry. Plan to divert <b>no more than about half</b> of the minimum flow, leaving the rest for fish, wildlife and downstream users.</p>')
    h.append('<ul><li><b>Bucket method (small streams, up to ~20 L/s):</b> build a temporary dam of boards, rocks or sandbags and route <i>all</i> the water through a pipe into a bucket of known size. Time the fill several times and average. Flow = volume ÷ time. Example: a 5-gal bucket fills in 6 s → 5 ÷ 6 × 60 = <b>50 gpm</b> (≈ 3.2 L/s).</li><li><b>Float method (larger streams):</b> pick a straight, even stretch 10–30 m (30–100 ft) long. Measure width and depth at several points to get the average cross-section area (A, m²). Time a floating object (orange, stick) over the stretch to get surface velocity (v = distance ÷ time). Water near the bottom is slower, so multiply by a correction factor: about <b>0.8</b> for smooth even channels, <b>0.6–0.7</b> for shallow rocky streams. Flow (m³/s) = A × v × factor; × 1,000 = L/s.</li><li><b>Weir method (most accurate for 1–100 L/s):</b> build a dam with a sharp-edged notch and measure the water height above the notch bottom at least 4 notch-heights upstream. For a 90° V-notch: <b>Q (L/s) ≈ 1,380 × h<sup>2.5</sup></b> (h in metres). Example: h = 0.10 m → 1,380 × 0.00316 ≈ 4.4 L/s (70 gpm).</li></ul>')
    h.append('<h2 id="power">3.2 How much power? The hydro formula</h2>')
    h.append('<div class="formula"><span class="eq">P (watts) = Net head (m) × Flow (L/s) × 9.81 × e</span><span class="eq">U.S. shortcut: P (W) ≈ Net head (ft) × Flow (gpm) ÷ 10</span>9.81 is gravity (m/s²). <b>e</b> = overall “water-to-wire” efficiency of turbine, generator, controller and wiring: about <b>0.5</b> (0.4–0.6) for small systems; up to 0.7 for well-built larger ones. The U.S. DOE shortcut assumes about 53%. <b>Daily energy (kWh) = P × 24 ÷ 1,000.</b></div>')
    h.append(table(["Worked example", "Net head", "Flow", "Efficiency", "Power", "Energy per day"], [
        ["A. Mountain spring creek (Pelton/Turgo)", "27 m (89 ft)", "10 L/s (158 gpm)", "0.50", "27 × 10 × 9.81 × 0.5 = <b>1,324 W</b>", "<b>31.8 kWh</b>"],
        ["B. Small hillside brook (U.S. units)", "50 ft (15.2 m)", "50 gpm (3.2 L/s)", "≈0.53", "50 × 50 ÷ 10 = <b>250 W</b>", "<b>6.0 kWh</b>"],
        ["C. Low-head mill site (propeller)", "3 m (9.8 ft)", "100 L/s (1,585 gpm)", "0.45", "3 × 100 × 9.81 × 0.45 = <b>1,324 W</b>", "<b>31.8 kWh</b>"],
        ["D. Tiny trickle, big drop", "100 m (328 ft)", "1 L/s (16 gpm)", "0.45", "100 × 1 × 9.81 × 0.45 = <b>441 W</b>", "<b>10.6 kWh</b>"]]))
    h.append('<p>Example B is a typical small homestead site: 250 W continuous sounds tiny, but 6 kWh a day is more than the essential-loads plan in Part 1, delivered day and night, rain or shine. Examples A and C show that high head/low flow and low head/high flow can give identical power — but C needs 10× the water through much larger, slower equipment.</p>')
    h.append('<h2 id="civil">3.3 Intake, screen and penstock</h2>')
    h.append('<p><b>Intake.</b> Use a low diversion weir (rock, concrete, or timber) or simply a pool where the stream naturally deepens. Divert water sideways into a <b>forebay/settling tank</b> (a barrel, plastic tank, or concrete box) where it slows down so sand settles out. Keep the penstock inlet submerged by at least several pipe diameters to stop air-sucking vortices. Screen the water: a sloped self-cleaning <b>Coanda screen</b> (0.5–1 mm wedge-wire) or a large-area stainless or perforated screen kept low velocity so leaves don’t plaster it. Provide an overflow back to the stream and a cleanout drain.</p>')
    h.append('<p><b>Penstock.</b> This is the pressurized pipe to the turbine and usually the most expensive part. Rules:</p>')
    h.append('<ul><li><b>Size for friction loss ≤ 10% of gross head</b> (5% if pipe is cheap relative to the value of power). Bigger pipe = less friction. Velocity is usually kept around 1–3 m/s (3–10 ft/s).</li><li><b>Pressure rating:</b> static pressure = 0.433 psi per foot of head (9.81 kPa per m). Choose pipe rated at least <b>1.5–2× the static pressure</b> at the bottom to survive water hammer, and close valves <i>slowly</i>. You can use lighter pipe at the top and heavier at the bottom.</li><li><b>Materials:</b> PVC (cheap, light; degrades in sunlight — bury or paint; brittle when frozen); HDPE poly pipe (flexible, tolerates freezing, comes in long rolls, joined by fusion or compression fittings); steel (high pressure, heavy). Avoid humps that rise above the line from the intake to the turbine — air collects there and chokes flow; add an air-release valve at any unavoidable high point.</li><li><b>Bury</b> it below frost depth where possible; anchor bends with concrete thrust blocks; install a gate or ball valve at the turbine and a pressure gauge just above it (gauge reading with water flowing = net head).</li></ul>')
    h.append('<p><b>Friction loss in Schedule 40 PVC, feet of head lost per 100 ft of pipe</b> (= metres per 100 m). Bold = good for long runs (≤1 per 100); grey = too high for most systems; “—” = velocity over 8 ft/s.</p>')
    h.append(friction_table())
    h.append('<p class="small">Hazen-Williams formula, C = 150 (new plastic pipe), Schedule 40 inside diameters. HDPE (SDR) pipe has a different inside diameter — check the maker’s friction chart. Add ~5–10% for fittings, screens and age.</p>')
    h.append('<h2 id="turbines">3.4 Choosing a turbine</h2>')
    h.append(table(["Turbine", "Head range (typical)", "Flow", "Efficiency", "Notes"], [
        ["<b>Pelton</b> (impulse)", "20 m (65 ft) to several hundred m; small units from ~10 m", "Low", "70–90%", "Spoon-shaped split buckets struck by 1–6 jets. Simple, robust, the standard for mountain sites. Works in open air above tailwater."],
        ["<b>Turgo</b> (impulse)", "10–250 m (30–800 ft)", "Low–medium", "70–85%", "Jet enters one side of runner and exits the other at an angle; handles more water than a Pelton of the same size and spins faster."],
        ["<b>Crossflow</b> (Banki-Michell)", "3–100 m (10–330 ft); best 5–50 m", "Medium–high", "60–80%", "Drum-shaped runner of curved blades; water passes through twice. Can be built in a farm workshop from steel pipe and plate; tolerates debris; good part-flow efficiency with a split gate."],
        ["<b>Propeller / Kaplan</b> (reaction)", "1.5–10 m (5–33 ft)", "High", "60–85%", "Like a boat propeller in a tube with a draft tube below. Kaplan has adjustable blades. For low-head sites with lots of water: mill dams, irrigation drops."],
        ["<b>Pump-as-turbine</b>", "10–80 m", "Medium", "50–70%", "Ordinary centrifugal pump run backward. Cheap and available; poor efficiency at part flow."],
        ["<b>Waterwheel</b> (overshot/breastshot)", "1–6 m (3–20 ft)", "Medium–high", "50–70%", "Slow (5–20 rpm) — needs large gear-up for electricity. Low-tech, repairable with wood and iron."]]))
    h.append(fig(D.turbine_chart(), "<b>Figure 6. Turbine selection by head and flow.</b> Plot your site’s net head and design flow; candidate turbines are those whose zone contains the point. Dotted lines show output at 50% overall efficiency."))
    h.append(fig(D.pelton(), "<b>Figure 7. Pelton wheel.</b> A high-velocity jet from the nozzle strikes split buckets at the pitch circle. For best efficiency the bucket speed should be about 0.46 × jet speed (just under half), so the water leaves with little velocity left."))
    h.append('<div class="formula"><span class="eq">Jet speed v ≈ 0.97 × √(2 × 9.81 × H) &nbsp; (m/s)</span><span class="eq">Runner rpm ≈ 60 × 0.46 × v ÷ (π × D)</span><span class="eq">Nozzle area = Q ÷ v &nbsp; → &nbsp; diameter = √(4 × area ÷ π)</span>H = net head (m), D = pitch-circle diameter (m), Q = flow per nozzle (m³/s). Use the rpm to match the runner to your alternator, either direct-coupled or with a belt.</div>')
    h.append('<h2 id="gen-hydro">3.5 Generators, controllers and dump loads</h2>')
    h.append('<p><b>Generators.</b> Most modern micro-hydro turbines use a <b>permanent-magnet alternator</b> (brushless, 3-phase): rugged, efficient and able to generate high voltage for long transmission lines. Alternatives: an <b>induction motor used as a generator</b> (cheap, robust, needs capacitors and a load controller); a <b>synchronous AC generator</b> with brushes and a voltage regulator (for larger AC-direct systems); or an automotive alternator for very small 12 V systems.</p>')
    h.append(danger("Never run a turbine without a load", "If a hydro turbine loses its electrical load it accelerates to <b>runaway speed</b> (roughly 1.8–2× normal for Pelton/Turgo, higher for propellers). Voltage can spike to several times normal, destroying controllers and appliances and possibly bursting the runner. Every system needs a <b>dump (diversion) load</b> that always absorbs whatever power isn’t being used — and a way to shut off the water safely."))
    h.append(fig(D.hydro_systems(), "<b>Figure 8. The two ways to wire a micro-hydro system.</b> Battery-based systems suit most homes; AC-direct systems need enough steady water to cover the household’s biggest peak."))
    h.append(table(["", "Battery-based", "AC-direct"], [
        ["Minimum practical size", "~100 W", "~2–3 kW (to start motors directly)"],
        ["How peaks are met", "Battery + inverter supply peaks of 3–10× the turbine output", "Turbine must produce the largest peak continuously"],
        ["Controller", "Diversion charge controller (or hydro-rated MPPT + diversion/clipper)", "Electronic Load Controller (ELC) or mechanical governor"],
        ["Dump load", "DC heating element (water or air) — must be rated for the system voltage", "AC heaters (water heater, space heaters)"],
        ["Pros / cons", "Very reliable, efficient use of small streams; batteries need replacing every 10–15 years (LiFePO4) or 5–10 (lead-acid)", "No batteries; but turbine, ELC and water supply must be larger; outages if flow drops"]]))
    h.append(caution("Dump-load elements and voltage", "A heating element’s wattage depends on the voltage: P = V² ÷ R. A 4,500 W, 240 V water-heater element (R ≈ 12.8 Ω) gives only <b>180 W at 48 V</b>. Buy elements rated for your system voltage, sized at least <b>125% of the turbine’s maximum output</b>, and use the heat (domestic hot water preheat, greenhouse or powerhouse heating)."))
    h.append('<h2 id="trans">3.6 Transmission wiring and voltage drop</h2>')
    h.append('<p>The best water is often far from the house. Wire resistance wastes power as heat and lowers voltage. Keep losses to about <b>3–5%</b> (up to 10% can be acceptable on long runs where copper is the expensive part).</p>')
    h.append('<div class="formula"><span class="eq">Voltage drop (V) = 2 × L × I × R ÷ 1000</span>L = one-way distance (ft), I = current (A), R = wire resistance in ohms per 1,000 ft (copper: 14 AWG 2.53, 12 AWG 1.59, 10 AWG 1.00, 8 AWG 0.63, 6 AWG 0.40, 4 AWG 0.25, 2 AWG 0.16, 1/0 0.098). Aluminum ≈ 1.6× copper resistance. For metric: R in Ω/km and L in km, drop = 2 × L × I × R.</div>')
    h.append('<p><b>Worked example — why voltage matters.</b> A 700 W turbine sits 400 ft (120 m) from the house. <b>At 48 V DC</b>, current = 700 ÷ 48 = 14.6 A. For a 3% drop (1.44 V): R ≤ 1.44 × 1000 ÷ (2 × 400 × 14.6) = 0.12 Ω/1000 ft → needs <b>1/0 AWG copper</b> — heavy and very expensive. <b>At 240 V</b> (a high-voltage turbine feeding a hydro-rated MPPT controller at the house, or a 240 V AC generator): current = 2.9 A; 3% = 7.2 V; R ≤ 3.1 Ω → <b>14 AWG</b> works, 12 AWG gives margin. Same power, one-twentieth the copper. Transmit at high voltage; convert at the house.</p>')
    h.append('<h2 id="ground">3.7 Grounding, freeze protection and maintenance</h2>')
    h.append('<p><b>Grounding and lightning.</b> Drive 8 ft (2.4 m) copper-clad ground rods at the powerhouse and at the house, bond all metal frames, pipe fittings and equipment cases, and tie both ends together through the cable’s ground conductor. Bury the transmission cable in conduit (overhead lines attract lightning); add surge arrestors at both ends. Use a ground-fault-protected supply for 120/240 V AC circuits.</p>')
    h.append('<p><b>Freezing.</b> Moving water rarely freezes in a buried pipe, so keep water flowing 24/7 all winter. Bury the penstock below frost depth or insulate it; put the intake in a deep, slow pool so frazil (slush) ice doesn’t block the screen; cover the intake box. Heat the powerhouse with part of the dump load. If you must shut down in deep cold, <b>drain</b> the penstock and turbine completely.</p>')
    h.append(check("Micro-hydro maintenance schedule", [
        "<b>Daily/after storms:</b> clean the intake screen; check the forebay level and pressure gauge (a drop in pressure = blockage or air)",
        "<b>Weekly:</b> log voltage, amps, kWh, battery state; listen for bearing noise or vibration; check dump-load operation",
        "<b>Monthly:</b> flush settling tank; inspect nozzle/spear for wear or debris; check belts and couplings; check battery water (lead-acid)",
        "<b>Yearly:</b> grease or replace bearings as specified; inspect runner buckets for erosion (sand wears them); walk the whole penstock for leaks, sags, exposed sections and anchor damage; tighten all electrical connections",
        "<b>Spares to keep:</b> bearings, seals, a spare nozzle/jet, screen material, pipe couplings and repair clamps, fuses, a spare controller or dump-load element"]))
    h.append(caution("Water rights and permits (in normal times)", "Building in or diverting a stream usually requires permission. In the U.S., western states follow ‘prior appropriation’ water rights and eastern states ‘riparian’ rights; you may need a state water-right permit, a state fish-and-wildlife stream permit, a U.S. Army Corps of Engineers Section 404 permit for work in waterways, and a FERC license or exemption (or a FERC determination that it isn’t required) for hydropower. In Canada, provinces issue water licences and federal Fisheries Act rules protect fish habitat. In Mexico, water use requires a CONAGUA concession. Return all water to the stream, screen fish out, and never dry up a stretch of stream."))
    # sample build
    loss = sample_numbers()
    h.append('<h2 id="anysite">3.8 Matching the design to your stream</h2>')
    h.append('<p>No two streams are alike. Use this table to find the closest match to your creek, then follow the design steps below. Output figures assume ~50% water-to-wire efficiency.</p>')
    h.append(table(["Site type", "Typical net head", "Typical usable flow", "Likely output", "Turbine", "Penstock / civil works", "Best electrical setup"], [
        ["<b>Steep spring or seep</b> (mountain, hillside)", "30–200 m (100–650 ft)", "0.3–3 L/s (5–50 gpm)", "50 W–2 kW", "Pelton (1–2 small nozzles) or Turgo", "Long small-diameter HDPE/PVC; high-pressure rating at bottom", "Battery-based; high-voltage transmission"],
        ["<b>Hillside creek</b> (Appalachia, PNW, Rockies, New England)", "10–60 m (30–200 ft)", "3–30 L/s (50–500 gpm)", "300 W–8 kW", "Turgo, multi-jet Pelton, or crossflow", "2–6 in pipe; intake weir + settling box", "Battery-based; AC-direct above ~3 kW"],
        ["<b>Gentle stream with a waterfall or ledge</b>", "3–10 m (10–33 ft)", "20–200 L/s", "300 W–10 kW", "Crossflow or propeller", "Short, large pipe or open flume; small dam", "Either; AC-direct if steady and ≥3 kW"],
        ["<b>Old mill dam / irrigation drop / canal</b>", "1.5–5 m (5–16 ft)", "50–1,000 L/s", "500 W–20 kW", "Propeller/Kaplan; waterwheel; low-head crossflow", "Intake from pond; draft tube; trash rack", "AC-direct with ELC, or battery-based"],
        ["<b>Flat river, no drop</b>", "< 1 m", "Large", "Small (≈ 50–500 W)", "Hydrokinetic ‘stream wheel’ or submerged propeller", "Anchored float or bank mount; no dam", "Battery-based (12–48 V)"],
        ["<b>Seasonal creek</b> (dries up in summer)", "Any", "Varies by season", "Seasonal", "As above", "Easy shut-down & drain; freeze/flood-proof", "Battery-based, paired with solar (sun is strongest when creeks are low)"]]))
    h.append('<p class="small">Hydrokinetic (‘run-of-river’ without head) machines extract only the moving water’s velocity: P ≈ ½ × 1,000 × A × v³ × 0.25 (A = rotor area m², v = current m/s). A 1 m² rotor in a 1.5 m/s current makes only ~420 W, so head is always worth looking for.</p>')
    h.append('<h3>Design steps for any site</h3>')
    h.append('<ol><li><b>Measure</b> head (two methods) and dry-season flow (several readings over weeks). Decide design flow = up to ~50% of minimum flow.</li><li><b>Calculate power</b> with the formula in 3.2. If it is under your essential load, plan a battery-based system (and maybe add solar); if it is several kW and steady, AC-direct is possible.</li><li><b>Pick a turbine</b> from Figure 6 and the table in 3.4. Check the maker’s range or plans; work out runner rpm and nozzle size from the formulas.</li><li><b>Choose penstock route and size</b> from the friction table: aim for ≤10% loss; check pressure rating (0.433 psi/ft or 9.81 kPa/m, × 1.5–2 for surge).</li><li><b>Choose transmission voltage</b>: short runs (&lt; 100 ft / 30 m) can be 12–48 V; longer runs need 120–400 V. Size wire with the voltage-drop formula.</li><li><b>Size controls and storage</b>: dump load ≥ 125% of max output; batteries for 1–2 days of peak use; inverter for the largest surge.</li><li><b>Plan seasons</b>: floods (protect intake, high-water bypass), freezing (bury, keep flowing), drought (reduce nozzles, rely on batteries/solar).</li></ol>')
    h.append(tip("Variable flow? Use several nozzles", "On Pelton and Turgo turbines, fit 2–4 nozzles of different sizes (or interchangeable nozzles). Close some in the dry season and open them all in the wet season, so the jet speed — and efficiency — stays high as flow changes. Crossflow turbines use a divided (1/3 + 2/3) inlet gate for the same purpose."))
    h.append('<h2 id="sample">3.9 Worked example: one typical hillside site</h2>')
    h.append('<p>This shows the design steps applied to one common case; substitute your own numbers. <b>Site.</b> A spring-fed creek with <b>120 ft (36.6 m) gross head</b> over <b>1,000 ft (305 m)</b> of pipe route; powerhouse 400 ft (120 m) from the house. Dry-season flow measured with a bucket at 130 gpm; design flow = <b>60 gpm (3.8 L/s)</b>, leaving more than half in the stream.</p>')
    h.append(table(["Step", "Calculation", "Result"], [
        ["1. Penstock size", f"2 in PVC at 60 gpm loses ~5.6 ft/100 ft → 56 ft (47% — far too much). 3 in PVC loses ~{loss/10:.2f} ft/100 ft → {loss:.1f} ft", f"<b>3 in pipe</b>, {loss/120*100:.0f}% loss"],
        ["2. Net head", f"120 − {loss:.0f} − ~3 ft (fittings, screen)", f"<b>≈ {120-loss-3:.0f} ft (33.2 m)</b>"],
        ["3. Pressure", "120 ft × 0.433 psi/ft = 52 psi static", "<b>Class 160–200 psi pipe</b> for bottom section"],
        ["4. Power", f"{120-loss-3:.0f} ft × 60 gpm ÷ 10  (≈ 33.2 m × 3.8 L/s × 9.81 × 0.53)", "<b>≈ 650 W continuous ≈ 15.6 kWh/day</b>"],
        ["5. Turbine", "36 m head, 3.8 L/s → Pelton or Turgo zone (Figure 6)", "<b>Pelton/Turgo with 2 nozzles</b>"],
        ["6. Jet & nozzles", "v = 0.97√(2 × 9.81 × 33.2) ≈ 25 m/s; each nozzle 1.9 L/s → area 7.6 cm² ... 0.0019 ÷ 25 = 7.6 × 10⁻⁵ m²", "<b>~10 mm (⅜ in) nozzles</b>"],
        ["7. Runner speed", "200 mm pitch diameter: 60 × 0.46 × 25 ÷ (π × 0.2)", "<b>≈ 1,100 rpm</b> — suits a PM alternator"],
        ["8. Transmission", "Generate at ~120–240 V DC/AC; 400 ft at ~3 A", "<b>12 AWG copper</b> in buried conduit, &lt;3% drop"],
        ["9. Battery bank", "1–2 days of storage for peaks (hydro recharges continuously)", "<b>48 V, 200 Ah LiFePO4 (~10 kWh)</b>"],
        ["10. Inverter", "Well pump surge + microwave + fridge", "<b>4–6 kW pure-sine 48 V inverter-charger</b>"],
        ["11. Controls", "Hydro-rated MPPT or rectifier + diversion controller; dump load ≥ 125% of 650 W", "<b>2 × 500 W, 48 V DC elements</b> in a hot-water preheat tank"]]).replace("area 7.6 cm² ... ", ""))
    h.append('<p>This system would supply about 15–16 kWh every day of the year — more than half of an average U.S. home’s use and three times the essential-loads plan — enough for refrigeration, freezer, well pump, lights, laundry, tools and electric hot-water preheating, with heating left to wood. Rough parts list: intake box and screen; ~1,000 ft of 3 in pipe with fittings, valves, gauge and air release; a commercial or homebuilt Pelton/Turgo turbine with PM alternator; ~400 ft of 12/3 direct-burial cable in conduit; controller, dump loads, LiFePO4 bank, inverter-charger, breakers and ground rods.</p>')
    h.append(check("Micro-hydro project checklist", ["Measured dry-season flow (several readings) and head (two methods agree)", "Calculated power; checked it covers the essential loads", "Chose pipe size for ≤10% loss and pressure rating with water-hammer margin", "Chose turbine type from head/flow; matched runner rpm to generator", "Designed intake with screen, settling tank, overflow and fish passage", "Planned dump load, controller, and turbine shut-off procedure", "Sized transmission voltage and wire for ≤3–5% loss", "Planned grounding, lightning protection and freeze protection", "Checked water rights/permits (normal times) and downstream users", "Stocked spares and wrote a maintenance log"]))
    return "\n".join(h)
